import http from 'http';
function main(): void {
  const events: string[] = [];
  const srv = http.createServer((req: any, res: any) => { res.end('x'); });
  srv.on('listening', () => events.push('listening')).on('close', () => events.push('close'));
  srv.listen(0, '127.0.0.1', () => {
    const closed = srv.close();
    events.push('close-returns-server:' + typeof closed.listen + ',' + closed.listening);
  });
  setTimeout(() => console.log(events.join(',')), 300);
}
